(window.DETAIL_C = window.DETAIL_C || {})["phy-12-12"] = {"phy-12-12-m01":{"idea":"Magnetic flux counts how much field passes through a surface.","steps":["Only the part of B along the normal passes through the surface.","So Φ = B A cos θ, where θ is the angle between B and the normal.","The unit is the weber: 1 Wb = 1 T m²."],"others":"B/A cos θ has the wrong dependence on area, and tesla is a field unit. tan θ and sin θ do not give the component along the normal.","trap":"θ is measured from the normal, not from the surface.","answer":"Φ = BA cosθ, with the unit weber (Wb)"},"phy-12-12-m02":{"idea":"Faraday's law: emf comes from the change of flux, not from the flux itself.","steps":["ε = −N dΦ/dt.","A faster or larger change of flux gives a bigger emf.","N turns give N times the emf of one turn."],"others":"Proportional to the flux itself is wrong, since a steady flux gives no emf. The emf depends on the number of turns. It does not depend on the resistance of the coil.","trap":"Rate of change, not the amount.","answer":"proportional to the rate of change of magnetic flux through the coil"},"phy-12-12-m03":{"idea":"Lenz's law says the induced current fights the change that caused it.","steps":["The minus sign in Faraday's law shows the opposition.","If the induced current helped the change, the effect would grow without limit.","That would create energy from nothing, so it opposes."],"others":"Always along the field, or always clockwise, are not general rules. Helping the change would break energy conservation.","trap":"Lenz's law is energy conservation.","answer":"opposes the change in flux that produced it"},"phy-12-12-m04":{"idea":"A coil resists an approaching magnet by making a matching pole facing it.","steps":["The flux through the coil increases as the north pole approaches.","The induced current makes a field against the increase.","So the near face becomes a north pole and repels the magnet."],"others":"A south pole would pull the magnet in, which helps the change. A south-then-north switch is not what happens. Neutral would mean no induced current, but there is one.","trap":"You must do work to push the magnet in.","answer":"a north pole, as the induced current opposes the approach"},"phy-12-12-m05":{"idea":"An emf appears only when the flux changes with time.","steps":["Faraday's law needs dΦ/dt.","A steady flux, however large, gives zero emf.","The flux changes if B, the area or the angle changes."],"others":"A strong field or a coil at rest in a steady field gives no emf. A large steady flux gives none either.","trap":"Steady means no emf.","answer":"the magnetic flux through the coil is changing with time"},"phy-12-12-m06":{"idea":"A rod moving across a field gets an emf ε = BLv.","steps":["Free charges in the rod feel a force qvB and move to one end.","The emf is the work per unit charge: ε = B L v.","The direction follows from Lenz's law."],"others":"BLv² has v squared. Bv/L and BL/v have the wrong dependence.","trap":"Length, speed and field all at right angles.","answer":"BLv"},"phy-12-12-m07":{"idea":"A rotating rod has a speed that grows from the pivot to the tip.","steps":["Speed at distance x is ωx, from 0 to ωL.","The average speed is ωL/2.","ε = B L × (ωL/2) = ½ B ω L²."],"others":"½BωL has the wrong power of L. BωL² and BωL lack the factor ½ or the second L.","trap":"L is squared, with a half.","answer":"½BωL²"},"phy-12-12-m08":{"idea":"An AC generator turns a coil in a field to make a changing flux.","steps":["A coil rotates in a magnetic field.","The flux through it changes: Φ = N B A cos ωt.","So an emf ε = N B A ω sin ωt is induced."],"others":"Attraction of iron, a current in a steady field and magnetisation by a current are other effects.","trap":"Rotation makes the flux change.","answer":"an emf is induced in a coil which rotates in a magnetic field, as the flux changes"},"phy-12-12-m09":{"idea":"The emf is largest when the flux changes fastest, which is when the flux is zero.","steps":["ε depends on dΦ/dt, not on Φ.","When the plane of the coil is parallel to B, the flux is zero but changing fastest.","So the emf is at its maximum then."],"others":"When the plane is perpendicular to B, the flux is largest but momentarily steady, so ε = 0. A stationary coil with no field gives no emf. 45° is not the maximum.","trap":"Maximum flux means zero emf.","answer":"parallel to the magnetic field, when the flux is zero"},"phy-12-12-m10":{"idea":"Household AC in India has a frequency of 50 Hz.","steps":["Power stations turn the coils so that the output repeats 50 times a second.","So the frequency is 50 Hz.","In the USA it is 60 Hz."],"others":"25 Hz, 100 Hz and 60 Hz are not the standard in India.","trap":"India 50 Hz, USA 60 Hz.","answer":"50 Hz"},"phy-12-12-m11":{"idea":"A running motor acts as a generator and makes a back emf.","steps":["The rotating armature cuts field lines.","An emf is induced, and by Lenz's law it opposes the supply.","It grows with the speed."],"others":"It is not zero while running. It does not add to the supply. It is below the supply voltage when the motor draws current.","trap":"I = (V − E)/R.","answer":"opposes the applied voltage and increases with the speed of the motor"},"phy-12-12-m12":{"idea":"A motor at rest has no back emf, so the starting current is large.","steps":["At the start, the armature is not turning, so E = 0.","I = V/R, and R is small, so I is large.","As the speed rises, E grows and the current falls."],"others":"The supply voltage is not higher. The resistance is not at its maximum. The back emf is zero at the start, not at its maximum.","trap":"That is why large motors use a starter resistance.","answer":"the armature is at rest, so there is no back emf to oppose the supply"},"phy-12-12-m13":{"idea":"Eddy currents are loops of current induced inside a piece of metal.","steps":["A changing flux through a metal piece induces currents.","They flow in closed loops inside the metal.","By Lenz's law they oppose the change, and they produce heat."],"others":"They do not flow only on water, in a wire from a battery or in insulators.","trap":"Eddy = whirlpool of current.","answer":"circulating currents induced in a piece of metal by a changing magnetic flux"},"phy-12-12-m14":{"idea":"Thin laminated sheets cut the paths of eddy currents.","steps":["A solid core would let large eddy currents flow.","Thin insulated sheets break up their paths.","So eddy currents and heat loss fall a lot."],"others":"Lamination does not stop magnetisation, does not raise winding resistance, and does not increase eddy currents.","trap":"Laminate to reduce loss.","answer":"reduce the eddy currents and the heat loss"},"phy-12-12-m15":{"idea":"Self-inductance links a coil's own flux to its own current.","steps":["The flux through a coil from its own current is proportional to the current: Φ = L I.","A changing current then induces ε = −L dI/dt.","L is measured in henry."],"others":"L/I and L²I are not proportional forms. LI² mixes the energy form with flux.","trap":"Φ = LI.","answer":"Φ = LI, or ε = −L dI/dt"},"phy-12-12-m16":{"idea":"Self-induced emf opposes any change of current, like inertia.","steps":["When the current rises, the induced emf is opposite and slows the rise.","When it falls, the emf is in the same direction and slows the fall.","So it opposes the change, not the current itself."],"others":"It exists when the current changes, not when it is steady. It does not help the change. It does not oppose the current itself.","trap":"L is like mass for current.","answer":"opposes the change in the current, and so acts like inertia for the current"},"phy-12-12-m17":{"idea":"A solenoid's inductance depends on its geometry.","steps":["B = μ₀ N I/l, so the flux through one turn is B A.","The flux linked with all turns is N B A = μ₀ N² A I/l.","L = Φ/I = μ₀ N² A/l."],"others":"The other forms have the wrong powers of N, A or l.","trap":"N is squared.","answer":"μ₀N²A/l"},"phy-12-12-m18":{"idea":"A coil stores energy in its magnetic field.","steps":["Work is done to build up the current against the induced emf.","That work is stored in the field.","U = ½ L I²."],"others":"L²I/2 has the wrong powers. ½LI lacks the square. LI² lacks the half.","trap":"Compare ½CV² and ½mv².","answer":"½LI²"},"phy-12-12-m19":{"idea":"Magnetic energy per unit volume is B²/(2μ₀).","steps":["For a solenoid, energy/volume = ½ L I²/(A l).","With B = μ₀ n I this becomes B²/(2μ₀).","Compare ½ε₀E² for an electric field."],"others":"B²/μ₀ lacks the half. B/(2μ₀) lacks the square. μ₀B²/2 has μ₀ in the wrong place.","trap":"B squared over 2μ₀.","answer":"B²/(2μ₀)"},"phy-12-12-m20":{"idea":"Mutual induction is between two coils.","steps":["The flux of the first coil passes through the second.","If the first current changes, so does the flux in the second.","An emf is induced in the nearby coil: ε₂ = −M dI₁/dt."],"others":"A magnet and a coil at rest with a steady field give no emf. A changing current inducing an emf in its own coil is self-induction. A steady current gives no emf.","trap":"Mutual: two coils. Self: one coil.","answer":"a changing current in one coil induces an emf in a nearby coil"},"phy-12-12-m21":{"idea":"Mutual inductance depends on geometry and the medium, not on the currents.","steps":["M depends on the size, shape and number of turns of the coils.","It also depends on their relative position and on the core material.","It does not depend on the current."],"others":"The distance, the turns and the core all affect M.","trap":"The question asks which does NOT matter.","answer":"the current flowing in either coil"},"phy-12-12-m22":{"idea":"A transformer works by mutual induction and needs AC.","steps":["AC in the primary makes a changing flux in the core.","The flux links the secondary and induces an emf.","A steady DC gives a steady flux and no emf."],"others":"It is not self-induction with DC. It is not the heating effect. DC only does not work.","trap":"No AC, no transformer action.","answer":"mutual induction, and it needs an alternating current to work"},"phy-12-12-m23":{"idea":"For an ideal transformer the voltage ratio follows the turns ratio, and the current ratio is the inverse.","steps":["V_s/V_p = N_s/N_p.","Power is conserved: V_p I_p = V_s I_s.","So I_p/I_s = V_s/V_p = N_s/N_p."],"others":"The other forms invert the current ratio or the turns ratio.","trap":"Step-up raises voltage but lowers current.","answer":"V_s/V_p = N_s/N_p = I_p/I_s"},"phy-12-12-m24":{"idea":"Real losses in a transformer are copper loss, iron loss and flux leakage.","steps":["Copper loss is I²R in the windings.","Iron loss is eddy currents and hysteresis in the core.","Flux leakage is flux that misses the secondary. No AC to DC conversion happens in the core."],"others":"Flux leakage, winding heating and eddy currents are all real losses.","trap":"The question asks for the one that is NOT a loss.","answer":"conversion of the alternating current into direct current in the core"},"phy-12-12-m25":{"idea":"A higher voltage means a lower current for the same power, so less heat in the lines.","steps":["P = V I, so I = P/V.","The loss in the lines is I²R.","A larger V means a smaller I, and the loss falls with the square of I."],"others":"High voltage does not increase the power the lines carry without loss. The other options misstate the reason.","trap":"That is why transmission is at 132 kV or more.","answer":"for the same power, a higher voltage means a lower current and so a smaller I²R loss in the lines"},"phy-12-12-m26":{"idea":"The henry follows from ε = L dI/dt.","steps":["L = ε/(dI/dt).","Unit: volt per (ampere per second).","That is volt second per ampere (V s/A)."],"others":"V/A is the ohm. V A/s and A s/V are not the unit of L.","trap":"Also 1 H = 1 Wb/A = 1 Ω s.","answer":"volt second per ampere (V s/A)"},"phy-12-12-n01":{"idea":"Induced emf is the number of turns times the rate of change of flux.","steps":["ΔΦ = 0.05 − 0.01 = 0.04 Wb.","ε = N ΔΦ/Δt = 100 × 0.04/0.2.","ε = 20.0 V."],"trap":"Multiply by the number of turns.","answer":"20.0 V"},"phy-12-12-n02":{"idea":"A rod moving across a field gets ε = BLv.","steps":["B = 0.5 T, L = 0.4 m, v = 5 m/s.","ε = 0.5 × 0.4 × 5.","ε = 1.00 V."],"trap":"All three are at right angles.","answer":"1.00 V"},"phy-12-12-n03":{"idea":"Peak emf of a generator is N B A ω.","steps":["ω = 2π f = 2π × 50 = 314.2 rad/s.","ε₀ = 200 × 0.2 × 0.05 × 314.2.","ε₀ = 628.3 V."],"trap":"Convert revolutions per second to rad/s.","answer":"628.3 V"},"phy-12-12-n04":{"idea":"Self-induced emf is L times the rate of change of current.","steps":["ε = L ΔI/Δt.","= 0.5 × 2.0/0.1.","= 10.0 V."],"trap":"Rate of change, not the current.","answer":"10.0 V"},"phy-12-12-n05":{"idea":"Energy in an inductor is ½LI².","steps":["L = 2 H and I = 3 A.","The current squared is I² = 9 A².","U = ½ × 2 × 9 = 9.0 J."],"trap":"Square the current.","answer":"9.0 J"},"phy-12-12-n06":{"idea":"Inductance of a solenoid: L = μ₀ n² A l.","steps":["n = 1000 per metre, A = 2 × 10⁻⁴ m², l = 0.5 m.","n² = 10⁶.","L = 4π × 10⁻⁷ × 10⁶ × 2 × 10⁻⁴ × 0.5 = 1.257 × 10⁻⁴ H = 125.7 μH."],"trap":"This equals μ₀N²A/l with N = n l.","answer":"125.7 μH"},"phy-12-12-n07":{"idea":"Mutual inductance: ε₂ = M dI₁/dt.","steps":["M = ε₂/(dI₁/dt).","ε₂ = 6 V and dI₁/dt = 3 A/s.","M = 2.0 H."],"trap":"Henry = volt second per ampere.","answer":"2.0 H"},"phy-12-12-n08":{"idea":"Secondary voltage follows the turns ratio.","steps":["V_s/V_p = N_s/N_p.","V_s = 220 × 50/500.","V_s = 22.0 V."],"trap":"Fewer turns in the secondary means a step-down.","answer":"22.0 V"},"phy-12-12-n09":{"idea":"An ideal transformer conserves power.","steps":["Input power = output power: V_p I_p = V_s I_s.","I_p = 22 × 10/220.","I_p = 1.0 A."],"trap":"Step-down: lower voltage, higher current on the secondary side.","answer":"1.0 A"},"phy-12-12-n10":{"idea":"Back emf is the supply voltage minus the drop across the armature resistance.","steps":["I = (V − E)/R.","E = V − I R = 220 − 10 × 2.","E = 200 V."],"trap":"The drop I R is only 20 V.","answer":"200 V"}};
